];
class Component extends DCLogic {
  state = { cur: { classic: 'INR', deluxe: 'INR', royal: 'INR', maharaja: 'INR' }, capA: 3 + Math.floor(Math.random() * 6), capB: 2 + Math.floor(Math.random() * 7), errPhone: '', errEmail: '', errMessage: '', errResult: '', mapLoaded: false, stickyOn: false };
  componentDidMount() {
    document.documentElement.lang = 'en';
    this._onScroll = () => {
      const on = window.scrollY > 640;
      if (on !== this.state.stickyOn) this.setState({ stickyOn: on });
    };
    window.addEventListener('scroll', this._onScroll, { passive: true });
    this._ctaScroll = () => {
      const y = window.scrollY;
      const nearEnd = (y + window.innerHeight) > (document.documentElement.scrollHeight - 140);
      const bar = y > 300;
      const priya = bar && !nearEnd;
      if (bar !== this.state.barOn || priya !== this.state.priyaOn) this.setState({ barOn: bar, priyaOn: priya });
    };
    window.addEventListener('scroll', this._ctaScroll, { passive: true });
    this._ctaScroll();
  }
  componentWillUnmount() { window.removeEventListener('scroll', this._onScroll); window.removeEventListener('scroll', this._ctaScroll); }
  renderVals() {
    const s = this.state;
    let params;
    try { params = new URLSearchParams(window.location.search); } catch (e) { params = new URLSearchParams(''); }
    const pick = (villa, cur) => () => this.setState(st => ({ cur: Object.assign({}, st.cur, { [villa]: cur }) }));
    const villas = VILLAS.map(v => {
      const cur = s.cur[v.key];
      const out = { name: v.name, href: v.href, img: v.img, alt: v.alt, signature: v.signature, desc: v.desc, single: v.prices[cur][0], double: v.prices[cur][1] };
      ['INR', 'Euro', 'USD'].forEach(c => {
        const on = cur === c;
        out['pick' + c] = pick(v.key, c);
        out['bg' + c] = on ? '#5A4420' : '#fff';
        out['fg' + c] = on ? '#F7F4EA' : '#5A4420';
        out['bd' + c] = on ? '#5A4420' : '#C9BFA8';
      });
      return out;
    });
    return {
      barO: this.state.barOn ? 1 : 0, barV: this.state.barOn ? 'visible' : 'hidden', barP: this.state.barOn ? 'auto' : 'none',
      priyaO: this.state.priyaOn ? 1 : 0, priyaV: this.state.priyaOn ? 'visible' : 'hidden', priyaP: this.state.priyaOn ? 'auto' : 'none',
      villas,
      stickyTransform: s.stickyOn ? 'translateY(0)' : 'translateY(-110%)',
      stickyPointer: s.stickyOn ? 'auto' : 'none',
      stickyVisibility: s.stickyOn ? 'visible' : 'hidden',
      stickyHidden: s.stickyOn ? 'false' : 'true',
      heritageYears: new Date().getFullYear() - 1908,
      captchaQuestion: 'How much is ' + s.capA + ' + ' + s.capB + ' ?',
      errPhone: s.errPhone, errEmail: s.errEmail, errMessage: s.errMessage, errResult: s.errResult,
      mapLoaded: s.mapLoaded, mapNotLoaded: !s.mapLoaded, loadMap: () => this.setState({ mapLoaded: true }),
      leadSourceUrl: (typeof window !== 'undefined' && window.location) ? window.location.href : '',
      utmSource: params.get('utm_source') || '', utmMedium: params.get('utm_medium') || '', utmCampaign: params.get('utm_campaign') || '', utmKeyword: params.get('utm_keyword') || '', utmContent: params.get('utm_content') || '',
      validateForm: (e) => {
        const f = e.target;
        const errs = { errPhone: '', errEmail: '', errMessage: '', errResult: '' };
        let ok = true;
        if (!f.fname.value.trim()) { ok = false; }
        if (!f.phone.value.trim() || !/^[+0-9()\-\s]{7,16}$/.test(f.phone.value.trim())) { errs.errPhone = 'Please enter a valid phone number.'; ok = false; }
        if (!f.email.value.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email.value.trim())) { errs.errEmail = 'Please enter a valid email id.'; ok = false; }
        if (parseInt(f.result.value, 10) !== this.state.capA + this.state.capB) { errs.errResult = 'Please answer the arithmetic check.'; ok = false; }
        this.setState(errs);
        if (!ok) { e.preventDefault(); return; }
      }
    };
  }
}
